const ALL_SATELLITES_QUERY_KEYWORDS = [
  'كل الاقمار','كل الأقمار','جميع الاقمار','جميع الأقمار','كل القمرات','كل الاقمار الصناعية','كل الأقمار الصناعية',
  'كل الساتلايت','كل الساتلايتات','كل السواتل','كل satellites','all satellites','all satellite','every satellite','any satellite',
  'كل قمر','على كل الاقمار','على كل الأقمار','بدون تحديد قمر','كل المدارات','جميع المدارات'
];

function detectAllSatellitesIntent(raw){
  const q = normalizeText(raw || '');
  const c = compactText(raw || '');
  if (!q && !c) return false;
  return ALL_SATELLITES_QUERY_KEYWORDS.some(function(term){
    const nt = normalizeText(term);
    const ct = compactText(term);
    return (nt && q.includes(nt)) || (ct && ct.length >= 4 && c.includes(ct));
  });
}

function isSatelliteControlToken(token, satellite, allSatellites){
  const tc = compactText(token);
  if (!tc) return true;
  if (allSatellites && ALL_SATELLITES_QUERY_KEYWORDS.some(function(term){
    const ct = compactText(term);
    return ct === tc || (ct.length >= 4 && (ct.includes(tc) || tc.includes(ct)));
  })) return true;
  if (allSatellites && ['كل','جميع','كافة','كامل','اقمار','الاقمار','أقمار','الأقمار','قمر','القمر','satellite','satellites','all','every','any'].some(function(term){ return compactText(term) === tc; })) return true;
  if (!satellite) return false;
  return Object.keys(SATELLITE_QUERY_KEYWORDS).some(function(key){
    return key === satellite && (SATELLITE_QUERY_KEYWORDS[key] || []).some(function(alias){
      const ac = compactText(alias);
      return ac && (ac === tc || (tc.length >= 3 && ac.includes(tc)) || (ac.length >= 3 && tc.includes(ac)));
    });
  });
}

function detectSatelliteFromQuery(raw){
  const q = normalizeText(raw || '');
  const c = compactText(raw || '');
  if (!q && !c) return null;
  for (const key of Object.keys(SATELLITE_QUERY_KEYWORDS)) {
    const aliases = SATELLITE_QUERY_KEYWORDS[key] || [];
    if (aliases.some(alias => {
      const nq = normalizeText(alias);
      const cq = compactText(alias);
      return (nq && q.includes(nq)) || (cq && cq.length >= 2 && c.includes(cq));
    })) return key;
  }
  return null;
}

